import{_ as t,a}from"./chunks/autorisations-accessibilite.CsvYiZQ4.js";import{_ as o,o as s,c as i,a2 as n}from"./chunks/framework.D9E58p8B.js";const g=JSON.parse('{"title":"Permissions","description":"","frontmatter":{"title":"Permissions"},"headers":[],"relativePath":"en/guide/autorisations.md","filePath":"en/guide/autorisations.md"}'),r={name:"en/guide/autorisations.md"};function h(d,e,c,l,p,m){return s(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h1><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><p>Daimon needs two permissions, both under <strong>System Settings › Privacy &amp; Security</strong>:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Used for</th><th>Organs concerned</th></tr></thead><tbody><tr><td><strong>Screen Recording</strong></td><td>Seeing the screen</td><td>Vue (Sight)</td></tr><tr><td><strong>Accessibility</strong></td><td>Reading the structure of windows and acting</td><td>Touché (Touch) and Mains (Hands)</td></tr></tbody></table><p>The setup walkthrough (panel › <strong>Relancer l&#39;installation…</strong> (Re-run setup…)) guides you through both permissions.</p><p>In each pane, the switch on the <strong>Daimon</strong> row must be on:</p><p><img src="'+t+'" alt="System Settings, Screen &amp; System Audio Recording pane: the Daimon row is enabled"></p><p><img src="'+a+'" alt="System Settings, Accessibility pane: the Daimon row is enabled"></p><p>These screenshots are cropped to the Daimon row, and they show the French interface: your panes also list the other applications you have allowed.</p><h3 id="the-responsible-process" tabindex="-1">The responsible process <a class="header-anchor" href="#the-responsible-process" aria-label="Permalink to &quot;The responsible process&quot;">​</a></h3><p>macOS ties these permissions to the application that <em>launches</em> Daimon: your AI client (its desktop app, your terminal, your editor). So it is that application you must grant them to, not Daimon itself.</p><p>If a tool fails, ask your AI to call <a href="/Daimon/en/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a>: it names the responsible application (key <code>responsible_app</code>) and says, for each permission, whether it is granted.</p><h3 id="without-accessibility" tabindex="-1">Without Accessibility <a class="header-anchor" href="#without-accessibility" aria-label="Permalink to &quot;Without Accessibility&quot;">​</a></h3><p>Without the Accessibility permission, some Mains tools report no error and have no effect. See <a href="./depannage.html">troubleshooting</a>.</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>No system permission needs to be granted (public README).</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./modele-mental.html">Mental model</a> or <a href="./depannage.html">troubleshooting</a>.</p>',18)])])}const f=o(r,[["render",h]]);export{g as __pageData,f as default};
